import { execa } from "execa";

const ENV = {
  GIT_OPTIONAL_LOCKS: "0",
  GIT_PAGER: "cat",
  LC_ALL: "C",
  GIT_TERMINAL_PROMPT: "0",
};

const BASE_ARGS = ["-c", "core.fsmonitor=false"];

export async function git(root: string, args: string[]): Promise<string> {
  const r = await execa("git", [...BASE_ARGS, ...args], { cwd: root, env: ENV });
  return r.stdout;
}

export async function isGitRepo(root: string): Promise<boolean> {
  try {
    await git(root, ["rev-parse", "--is-inside-work-tree"]);
    return true;
  } catch {
    return false;
  }
}

export async function collectGitState(root: string) {
  const branch = (await git(root, ["rev-parse", "--abbrev-ref", "HEAD"])).trim();
  const head = (await git(root, ["rev-parse", "HEAD"])).trim();
  const recentCommits = (await git(root, ["log", "-5", "--oneline"])).trim().split("\n").filter(Boolean);
  const status = await git(root, ["status", "--porcelain"]);
  const stagedDiff = await git(root, ["diff", "--cached", "--no-ext-diff", "--no-textconv"]);
  const unstagedDiff = await git(root, ["diff", "--no-ext-diff", "--no-textconv"]);
  const untrackedRaw = await git(root, ["ls-files", "--others", "--exclude-standard"]);
  const untrackedPaths = untrackedRaw.trim().split("\n").filter(Boolean);
  return { branch, head, recentCommits, status, stagedDiff, unstagedDiff, untrackedPaths };
}

import { realpathSync } from "node:fs";
import path from "node:path";

export function resolveRoot(input: string): string {
  return realpathSync(input);
}

export function ensureInside(root: string, target: string): string {
  const resolved = path.resolve(root, target);
  if (!resolved.startsWith(root + path.sep) && resolved !== root) {
    throw new Error("Path outside root");
  }
  return resolved;
}

#!/usr/bin/env node
import { parseArgs } from "node:util";
import { resolveRoot, ensureInside } from "./guard.js";
import { collectGitState, isGitRepo } from "./git.js";
import { writeFile } from "./io.js";
import { PacketSchema } from "../core/schema.js";
import { canonicalJson, computeHash } from "../core/serializer.js";
import { redactText, isDenylistedPath } from "../core/redactor.js";
import { renderMarkdown } from "../core/prompt.js";
import { applyBudget } from "../core/budget.js";

async function main() {
  const { values, positionals } = parseArgs({
    args: process.argv.slice(2),
    options: {
      root: { type: "string", default: "." },
      out: { type: "string", default: "port0-packet.json" },
      format: { type: "string", default: "json" },
      intent: { type: "string", default: "" },
      "test-log": { type: "string" },
      "max-bytes": { type: "string", default: "204800" },
    },
    allowPositionals: true,
  });

  const cmd = positionals[0];

  if (cmd === "verify") {
    // minimal: validate schema + hash
    const fs = await import("node:fs");
    const raw = fs.readFileSync(positionals[1]!, "utf8");
    const parsed = JSON.parse(raw);
    PacketSchema.parse(parsed);
    console.log("OK");
    process.exit(0);
  }

  if (cmd === "render") {
    const fs = await import("node:fs");
    const raw = fs.readFileSync(positionals[1]!, "utf8");
    const parsed = JSON.parse(raw);
    console.log(renderMarkdown(parsed, "1.0.0"));
    process.exit(0);
  }

  // default export
  const root = resolveRoot(values.root as string);
  if (!(await isGitRepo(root))) {
    console.error("Not a git repo");
    process.exit(1);
  }

  const state = await collectGitState(root);
  const denylisted: string[] = [];
  const untracked: { path: string; content: string }[] = [];
  for (const p of state.untrackedPaths) {
    if (isDenylistedPath(p)) {
      denylisted.push(p);
      continue;
    }
    const fs = await import("node:fs");
    const content = fs.readFileSync(root + "/" + p, "utf8");
    const r = redactText(content);
    untracked.push({ path: p, content: r.text });
  }

  const stagedRedacted = redactText(state.stagedDiff);
  const unstagedRedacted = redactText(state.unstagedDiff);

  let testLog = "";
  if (values["test-log"]) {
    if (values["test-log"] === "-") {
      const chunks: Buffer[] = [];
      for await (const c of process.stdin) chunks.push(c as Buffer);
      testLog = Buffer.concat(chunks).toString("utf8");
    } else {
      const fs = await import("node:fs");
      testLog = fs.readFileSync(values["test-log"] as string, "utf8");
    }
  }
  const testRedacted = redactText(testLog);

  const maxBytes = Number(values["max-bytes"]);
  const sections: Record<string, string> = {
    staged: stagedRedacted.text,
    unstaged: unstagedRedacted.text,
    untracked: untracked.map((u) => u.content).join("\n"),
    testLog: testRedacted.text,
  };
  const budgeted = applyBudget(sections, maxBytes);

  const packet = {
    schemaVersion: "1",
    repo: {
      rootName: root.split(/[\\/]/).pop() ?? "repo",
      branch: state.branch,
      head: state.head,
      recentCommits: state.recentCommits,
    },
    intent: values.intent as string,
    status: state.status,
    stagedDiff: budgeted.sections.staged,
    unstagedDiff: budgeted.sections.unstaged,
    untracked,
    testLog: budgeted.sections.testLog,
    redaction: {
      counts: { ...stagedRedacted.counts, ...unstagedRedacted.counts, ...testRedacted.counts },
      denylisted,
    },
    budget: {
      omittedFiles: budgeted.omittedFiles,
      truncated: budgeted.truncated,
    },
  };

  const contentHash = await computeHash(packet as Record<string, unknown>);
  const finalPacket = { ...packet, contentHash };
  PacketSchema.parse(finalPacket);

  const outPath = ensureInside(root, values.out as string);
  writeFile(outPath, canonicalJson(finalPacket));

  if (values.format === "md" || values.format === "both") {
    const mdPath = outPath.replace(/\.json$/, ".md");
    writeFile(mdPath, renderMarkdown(finalPacket, "1.0.0"));
  }

  console.log(`Wrote ${outPath}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

import { writeFileSync } from "node:fs";

export function writeFile(filePath: string, content: string): void {
  writeFileSync(filePath, content, "utf8");
}

export interface BudgetResult {
  omittedFiles: string[];
  truncated: string[];
}

export function applyBudget<T>(sections: Record<string, string>, maxBytes: number): { sections: Record<string, string>; omittedFiles: string[]; truncated: string[] } {
  const omittedFiles: string[] = [];
  const truncated: string[] = [];
  // Simple placeholder: if total exceeds, truncate untracked contents first
  let total = Object.values(sections).reduce((a, b) => a + Buffer.byteLength(b, "utf8"), 0);
  const order = ["untracked", "unstaged", "staged", "testLog"];
  for (const key of order) {
    if (total <= maxBytes) break;
    if (sections[key]) {
      const original = sections[key];
      const cut = Math.max(0, Math.floor(original.length * 0.5));
      sections[key] = original.slice(0, cut) + "\n[TRUNCATED]";
      truncated.push(key);
      total = Object.values(sections).reduce((a, b) => a + Buffer.byteLength(b, "utf8"), 0);
    }
  }
  return { sections, omittedFiles, truncated };
}

export function renderMarkdown(packet: any, version: string): string {
  return `# Port0 Packet

## Task intent
${packet.intent}

## Repo state
Branch: ${packet.repo.branch}
HEAD: ${packet.repo.head}

## Failing tests
${packet.testLog}

## Staged diff
${packet.stagedDiff}

## Unstaged diff
${packet.unstagedDiff}

## Untracked files
${packet.untracked.map((f: any) => f.path).join("\n")}

Safety: redacted ${JSON.stringify(packet.redaction.counts)}; denylisted ${packet.redaction.denylisted.join(", ")}

---
hash: ${packet.contentHash}
version: ${version}
`;
}
